package brandmark

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

// File is one generated file, its path relative to the repository root.
type File struct {
	Path string
	Data []byte
}

// Sprite is the canonical source: #mark lives here, and the tray-* symbols are generated next to it.
const Sprite = "ui/v1/src/icons.svg"

const (
	trayBegin = "  <!-- Tray states, derived from #mark by tray/cmd/brandgen: do not edit by hand. -->\n"
	trayEnd   = "  <!-- End of the generated tray states. -->\n"
)

// The web icons exist twice: ui/v1/public is the source and public/v1 the committed build output
// (vite copies one into the other). The generator writes both.
var webDirs = []string{"ui/v1/public", "public/v1"}

// Generate makes every file derived from #mark, reading the repository at root.
func Generate(root string) ([]File, error) {
	read := func(path string) (string, error) {
		data, err := os.ReadFile(filepath.Join(root, path))
		return string(data), err
	}
	sprite, err := read(Sprite)
	if err != nil {
		return nil, err
	}
	m, err := ParseMark(sprite)
	if err != nil {
		return nil, err
	}
	manifest, err := read("ui/v1/public/manifest.webmanifest")
	if err != nil {
		return nil, err
	}
	tokens, err := read("ui/v1/src/tokens.css")
	if err != nil {
		return nil, err
	}
	// The web app tile is the manifest's background colour; the macOS tile is the ink plate (--n-900).
	webTile, err := find(manifest, `"background_color":\s*"(#[0-9a-f]{6})"`, "the manifest background_color")
	if err != nil {
		return nil, err
	}
	appTile, err := find(tokens, `--n-900:\s*(#[0-9a-f]{6})`, "the --n-900 token")
	if err != nil {
		return nil, err
	}
	webColor, err := HexColor(webTile)
	if err != nil {
		return nil, err
	}
	appColor, err := HexColor(appTile)
	if err != nil {
		return nil, err
	}

	var files []File
	add := func(path string, data []byte) { files = append(files, File{path, data}) }

	// The tray-* symbols, next to #mark.
	begin, end := strings.Index(sprite, trayBegin), strings.Index(sprite, trayEnd)
	if begin < 0 || end < begin {
		return nil, fmt.Errorf("brandmark: %s lacks the generated tray-states markers", Sprite)
	}
	var symbols strings.Builder
	for _, s := range States {
		fmt.Fprintf(&symbols, "  <symbol id=\"tray-%s\" viewBox=\"0 0 %s %s\">%s</symbol>\n", s, num(m.Side), num(m.Side), m.StateGlyph(s).SVG())
	}
	add(Sprite, []byte(sprite[:begin+len(trayBegin)]+symbols.String()+sprite[end:]))

	// The tray reads the mark from a copy compiled into it.
	add("tray/internal/brandmark/mark_gen.go", []byte("// Code generated by tray/cmd/brandgen from #mark in "+Sprite+". DO NOT EDIT.\n\npackage brandmark\n\n"+
		"// MarkSymbol is the #mark symbol, for the tray.\nconst MarkSymbol = "+fmt.Sprintf("%q", m.Symbol)+"\n"))

	favicon := `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ` + num(m.Side) + ` ` + num(m.Side) + `" role="img" aria-labelledby="title">
  <title id="title">Faravan — Open horizon</title>
  ` + m.Inner + `
</svg>
`
	ico := newCanvas(32)
	ink, err := HexColor(m.Color)
	if err != nil {
		return nil, err
	}
	ico.paint(Coverage(m.Glyph, m.Side, 32, 0, 0, 32), ink, 255)
	icoData, err := ICO(ico.png())
	if err != nil {
		return nil, err
	}
	// Web app icons: the mark fills the frame on the manifest colour; the maskable one keeps it
	// inside the central 75%, so a launcher's mask never cuts it.
	web := []struct {
		name      string
		size      int
		boxFactor float64
	}{{"apple-touch-icon.png", 180, 1}, {"icon-192.png", 192, 1}, {"icon-512.png", 512, 1}, {"icon-maskable-512.png", 512, 0.75}}
	for _, dir := range webDirs {
		add(dir+"/favicon.svg", []byte(favicon))
		add(dir+"/favicon.ico", icoData)
		for _, icon := range web {
			c, err := m.tile(icon.size, float64(icon.size)*icon.boxFactor, webColor)
			if err != nil {
				return nil, err
			}
			add(dir+"/"+icon.name, c.png())
		}
	}

	add("packaging/macos/icon/Faravan.svg", []byte(m.AppIconSVG(appTile)))
	for _, size := range []int{16, 32, 128, 256, 512} {
		for _, scale := range []int{1, 2} {
			name := fmt.Sprintf("icon_%dx%d.png", size, size)
			if scale == 2 {
				name = fmt.Sprintf("icon_%dx%d@2x.png", size, size)
			}
			data, err := m.AppIcon(size*scale, appColor)
			if err != nil {
				return nil, err
			}
			add("packaging/macos/icon/Faravan.iconset/"+name, data)
		}
	}
	return files, nil
}

func find(text, pattern, what string) (string, error) {
	found := regexp.MustCompile(pattern).FindStringSubmatch(text)
	if found == nil {
		return "", fmt.Errorf("brandmark: could not read %s", what)
	}
	return found[1], nil
}

func num(v float64) string {
	return strings.TrimSuffix(strings.TrimRight(fmt.Sprintf("%.6f", v), "0"), ".")
}

// Write puts the generated files under root.
func Write(root string, files []File) error {
	for _, f := range files {
		path := filepath.Join(root, f.Path)
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
			return err
		}
		if err := os.WriteFile(path, f.Data, 0o644); err != nil {
			return err
		}
	}
	return nil
}
